     1	import Foundation
     2	
     3	/// Umbrella for anything `AppController` can hold as the active STT engine,
     4	/// whether batch (`TranscriptionEngine`) or streaming
     5	/// (`StreamingTranscriptionEngine`). Lets the controller keep one `engine`
     6	/// slot and branch on capability with `as?`.
     7	public protocol TranscriptionProviding: AnyObject {}
     8	
     9	/// Batch STT seam: a complete WAV in, transcript out. Groq today, whisper.cpp.
    10	/// `prompt` is optional decoder biasing (the context-selected vocabulary).
    11	public protocol TranscriptionEngine: TranscriptionProviding {
    12	    func transcribe(wav: Data, prompt: String?) async throws -> String
    13	}
    14	
    15	public extension TranscriptionEngine {
    16	    /// Convenience for callers (and tests) that don't bias the decoder.
    17	    func transcribe(wav: Data) async throws -> String {
    18	        try await transcribe(wav: wav, prompt: nil)
    19	    }
    20	}
    21	
    22	/// Streaming STT seam (Kyutai): audio is fed incrementally *during* the hold and
    23	/// finalized on release, so latency is a fixed flush rather than scaling with
    24	/// utterance length.
    25	public protocol StreamingTranscriptionEngine: TranscriptionProviding {
    26	    func makeSession() throws -> TranscriptionSession
    27	}
    28	
    29	/// One push-to-talk utterance's worth of streaming transcription.
    30	public protocol TranscriptionSession: AnyObject {
    31	    /// Invoked on the main thread with the transcript-so-far as words arrive.
    32	    var onPartial: ((String) -> Void)? { get set }
    33	    /// Feed mic audio (24 kHz mono Float32). Called from the audio thread — must
    34	    /// not block (enqueue and return).
    35	    func append(_ pcm: [Float])
    36	    /// Flush the model and return the final transcript. Called once, on release.
    37	    func finish() async throws -> String
    38	    /// Discard the in-flight stream without finalizing (too-short tap / abort).
    39	    func cancel()
    40	}
    41	
    42	/// Engines that own a child server process and must be torn down on app quit.
    43	public protocol LocalServerEngine: AnyObject {
    44	    func shutdown()
    45	}
    46	
    47	/// A local model server whose memory macOS takes back while it idles on a Mac
    48	/// short of memory: llama-server's mapped model file drops out of the page
    49	/// cache, and the rest is compressed or swapped. The next request waits while
    50	/// the weights come back: after 10 GB of other file reads, a 5 s dictation on
    51	/// Qwen3-ASR 1.7B and the 3B cleanup model took 5.4 to 7.8 s (0.6 to 1.0 s
    52	/// warm, M3 Pro, 36 GB). Started at key-down, the same page-in runs while the
    53	/// user speaks: 0.9 s after a 3 s hold, 1.3 to 1.5 s after a 1 s hold.
    54	public protocol Prewarmable: AnyObject {
    55	    /// Sends one minimal request through the same server checks as a real
    56	    /// one, so the model pages in while the user is still speaking. `prompt`
    57	    /// is the one the next real request carries (vocabulary or cleanup
    58	    /// system prompt), so the server caches its prefix. The task answers
    59	    /// whether the server replied 200; the app ignores it.
    60	    @discardableResult
    61	    func prewarm(prompt: String?) -> Task<Bool, Never>
    62	}
    63	
    64	public enum Prewarm {
    65	    /// One second of 16 kHz silence: every layer of an audio model runs on it,
    66	    /// and a resident model handles it in tens of milliseconds.
    67	    public static let silence = WAVEncoder.encode(samples: [Int16](repeating: 0, count: 16_000),
    68	                                                  sampleRate: 16_000)
    69	
    70	    /// Key-down: warms what the coming dictation calls, the batch STT engine
    71	    /// with the dictation's vocabulary prompt and the local cleanup model.
    72	    /// Streaming and cloud engines have nothing to warm. whisper-server is
    73	    /// left out: it encodes a full 30 s window for any request and serves one
    74	    /// request at a time, so on a warm server a prewarm delayed a 0.25 s
    75	    /// dictation by 0.4 s.
    76	    @discardableResult
    77	    public static func forDictation(engine: TranscriptionProviding?, cleaner: Cleaner?,
    78	                                    prompt: String?) -> [Task<Bool, Never>] {
    79	        var tasks: [Task<Bool, Never>] = []
    80	        if let local = engine as? Prewarmable { tasks.append(local.prewarm(prompt: prompt)) }
    81	        if let cleanup = cleaner?.prewarm() { tasks.append(cleanup) }
    82	        return tasks
    83	    }
    84	
    85	    /// Asks the kernel to read the whole file into the page cache (fcntl
    86	    /// F_RDADVISE) and returns once it has. Blocks: call it off the main
    87	    /// thread. False when the file cannot be opened or the advice is refused.
    88	    @discardableResult
    89	    public static func readAhead(_ path: String) -> Bool {
    90	        let fd = open(path, O_RDONLY)
    91	        guard fd >= 0 else { return false }
    92	        defer { close(fd) }
    93	        var info = stat()
    94	        guard fstat(fd, &info) == 0 else { return false }
    95	        let chunk: off_t = 1 << 30 // ra_count is an Int32
    96	        var offset: off_t = 0
    97	        while offset < info.st_size {
    98	            var advice = radvisory(ra_offset: offset, ra_count: Int32(min(chunk, info.st_size - offset)))
    99	            guard fcntl(fd, F_RDADVISE, &advice) == 0 else { return false }
   100	            offset += chunk
   101	        }
   102	        return true
   103	    }
   104	
   105	    /// `readAhead` on a GCD thread, so the blocking read never holds one of
   106	    /// Swift concurrency's few threads.
   107	    static func readAheadInBackground(_ path: String) async {
   108	        await withCheckedContinuation { (done: CheckedContinuation<Void, Never>) in
   109	            DispatchQueue.global(qos: .userInitiated).async {
   110	                readAhead(path)
   111	                done.resume()
   112	            }
   113	        }
   114	    }
   115	
   116	    /// True when the request got a 200; false on any error.
   117	    static func send(_ request: URLRequest?, with session: URLSession) async -> Bool {
   118	        guard let request, let (_, response) = try? await session.data(for: request) else { return false }
   119	        return (response as? HTTPURLResponse)?.statusCode == 200
   120	    }
   121	}
   122	
   123	/// Seam for the cleanup LLM, mockable in tests.
   124	public protocol ChatEngine {
   125	    func chatComplete(system: String, user: String, maxTokens: Int) async throws -> String
   126	}
