 21	/// Local transcription with NVIDIA Parakeet TDT through parakeet.cpp's
 22	/// `parakeet-server` (OpenAI-style `/v1/audio/transcriptions`), kept warm as a
 23	/// child process. Parakeet decodes greedily and takes no prompt, so vocabulary
 24	/// repair is left to `TranscriptCorrector` and the cleanup pass.
 25	public final class ParakeetEngine: TranscriptionEngine, LocalServerEngine, Prewarmable {
 26	    /// Attention cost grows with the square of the length: on an M3 Pro a
 27	    /// 600 s recording takes 43 s and 3.3 GB in one pass, 7.9 s in 60 s chunks.
 28	    public static let maxChunkSeconds = 60.0
 29	
 30	    private let binaryPath: String
 31	    private let modelPath: String
 32	    private let session: URLSession
 33	    private let server: ChildServer
 34	
 35	    public init(binaryPath: String, modelPath: String, port: Int,
 36	                session: URLSession = LoopbackURLSession.make(resourceTimeout: 90)) {
 37	        let binary = (binaryPath as NSString).expandingTildeInPath
 38	        let model = (modelPath as NSString).expandingTildeInPath
 39	        self.binaryPath = binary
 40	        self.modelPath = model
 41	        self.session = session
 42	        self.server = ChildServer(name: "parakeet-server", binaryPath: binary, port: port,
 43	                                  session: session) { port in
 44	            Self.serverArguments(modelPath: model, port: port)
 45	        }
 46	    }
 47	
 48	    deinit { shutdown() }
 49	
 50	    /// `prompt` is ignored: Parakeet has no decoder prompt.
 51	    public func transcribe(wav: Data, prompt: String?) async throws -> String {
 52	        try await ensureServerRunning()
 53	        return try await AudioChunker.transcribe(wav: wav, maxSeconds: Self.maxChunkSeconds) { piece in
 54	            try await ensureServerRunning() // a retry after a crash respawns the server
 55	            let request = Self.makeTranscriptionRequest(wav: piece, port: server.port)
 56	            let (data, response) = try await session.data(for: request)
 57	            let status = (response as? HTTPURLResponse)?.statusCode ?? 0
 58	            guard status == 200 else { throw ParakeetError.http(status: status) }
 59	            return try Self.parseResponse(data)
 60	        }
 61	    }
 62	
 63	    /// Spawns the server eagerly so the model is warm before the first
 64	    /// utterance. Safe to call repeatedly.
 65	    public func warmUp() {
 66	        Task.detached { [weak self] in try? await self?.ensureServerRunning() }
 67	    }
 68	
 69	    /// `prompt` is ignored, as in `transcribe`.
 70	    @discardableResult
 71	    public func prewarm(prompt: String?) -> Task<Bool, Never> {
 72	        Task.detached { [weak self] in
 73	            guard let self, (try? await self.ensureServerRunning()) != nil else { return false }
 74	            return await Prewarm.send(Self.makePrewarmRequest(port: self.server.port), with: self.session)
 75	        }
 76	    }
 77	
 78	    public func shutdown() {
 79	        server.shutdown()
 80	    }
 81	
 82	    private func ensureServerRunning() async throws {
 83	        let ready = try await server.ensureRunning(polls: 120) {
 84	            guard LocalServer.isSafeToExecute(binaryPath) else {
 85	                throw ParakeetError.binaryMissing(binaryPath)
 86	            }
 87	            guard FileManager.default.fileExists(atPath: modelPath) else {
 88	                throw ParakeetError.modelMissing(modelPath)
 89	            }
 90	        }
 91	        guard ready else { throw ParakeetError.serverTimeout }
 92	    }
 93	
 94	    // MARK: pure request/argument builders (unit-tested)
 95	
 96	    /// The model is always an existing local file: parakeet-server treats any
 97	    /// other `--model` value as a name or URL to download.
 98	    public static func serverArguments(modelPath: String, port: Int) -> [String] {
 99	        ["--model", modelPath,
100	         "--host", "127.0.0.1",
101	         "--port", String(port),
102	         "--threads", String(max(4, ProcessInfo.processInfo.activeProcessorCount / 2))]
103	    }
104	
105	    public static func makePrewarmRequest(port: Int) -> URLRequest {
106	        makeTranscriptionRequest(wav: Prewarm.silence, port: port)
107	    }
108	
109	    public static func makeTranscriptionRequest(wav: Data, port: Int) -> URLRequest {
110	        var multipart = MultipartBody()
111	        multipart.addField(name: "response_format", value: "json")
112	        multipart.addFile(name: "file", filename: "audio.wav", contentType: "audio/wav", data: wav)
113	        var request = URLRequest(url: URL(string: "http://127.0.0.1:\(port)/v1/audio/transcriptions")!)
114	        request.httpMethod = "POST"
115	        request.setValue(multipart.contentType, forHTTPHeaderField: "Content-Type")
116	        request.httpBody = multipart.finalized()
117	        request.timeoutInterval = 60
118	        return request
119	    }
120	
121	    public static func parseResponse(_ data: Data) throws -> String {
122	        struct Response: Decodable { let text: String }
123	        guard let response = try? JSONDecoder().decode(Response.self, from: data) else {
124	            throw ParakeetError.badResponse
125	        }
126	        return response.text.trimmingCharacters(in: .whitespacesAndNewlines)
127	    }
128	}

