 94	    // MARK: pure request/argument builders (unit-tested)
 95	
 96	    /// The model is always an existing local file: parakeet-server treats any
 97	    /// other `--model` value as a name or URL to download.
 98	    public static func serverArguments(modelPath: String, port: Int) -> [String] {
 99	        ["--model", modelPath,
100	         "--host", "127.0.0.1",
101	         "--port", String(port),
102	         "--threads", String(max(4, ProcessInfo.processInfo.activeProcessorCount / 2))]
103	    }
104	
105	    public static func makePrewarmRequest(port: Int) -> URLRequest {
106	        makeTranscriptionRequest(wav: Prewarm.silence, port: port)
107	    }
108	
109	    public static func makeTranscriptionRequest(wav: Data, port: Int) -> URLRequest {
110	        var multipart = MultipartBody()
111	        multipart.addField(name: "response_format", value: "json")
112	        multipart.addFile(name: "file", filename: "audio.wav", contentType: "audio/wav", data: wav)
113	        var request = URLRequest(url: URL(string: "http://127.0.0.1:\(port)/v1/audio/transcriptions")!)
114	        request.httpMethod = "POST"
115	        request.setValue(multipart.contentType, forHTTPHeaderField: "Content-Type")
116	        request.httpBody = multipart.finalized()
117	        request.timeoutInterval = 60
118	        return request
119	    }
120	
121	    public static func parseResponse(_ data: Data) throws -> String {
122	        struct Response: Decodable { let text: String }
123	        guard let response = try? JSONDecoder().decode(Response.self, from: data) else {
124	            throw ParakeetError.badResponse
125	        }
126	        return response.text.trimmingCharacters(in: .whitespacesAndNewlines)
127	    }
128	}

