  1	import Foundation
  2	
  3	/// The warm loopback server process behind a local engine. Reuses a verified
  4	/// orphan of its own binary on the preferred port, otherwise spawns a child
  5	/// (on a private port when a foreign process holds the preferred one), then
  6	/// polls `GET /health` until it answers 200. A spawned child counts as ready
  7	/// only once it (or a process it started) is seen listening on the port:
  8	/// `lsof` cannot see another user's listener when the port is picked, and
  9	/// audio must never reach a squatter that answered in the child's place.
 10	///
 11	/// Callers overlap (warm-up, dictation, an engine switch), so one start runs
 12	/// at a time and the shared state sits behind a lock. A child that fails
 13	/// before it is ready sends the next start to a fresh port. `shutdown()`
 14	/// retires the server (app quit, engine switch): a start under way or begun
 15	/// later leaves nothing running and reports not ready.
 16	public final class ChildServer {
 17	    private let name: String
 18	    private let binaryPath: String
 19	    private let preferredPort: Int
 20	    private let session: URLSession
 21	    private let arguments: (Int) -> [String]
 22	    private let owns: (pid_t, Int) -> Bool
 23	    private let gate = StartGate()
 24	    private let lock = NSLock()
 25	    // Guarded by `lock`.
 26	    private var process: Process?
 27	    private var verified = false
 28	    private var currentPort: Int
 29	    private var avoidPreferredPort = false
 30	    private var retired = false
 31	
 32	    /// `arguments` builds the command line for the port the child binds.
 33	    /// `owns` tells whether a pid holds the port (tests replace the lsof check).
 34	    public init(name: String, binaryPath: String, port: Int, session: URLSession,
 35	                owns: @escaping (pid_t, Int) -> Bool = ChildServer.listens(pid:port:),
 36	                arguments: @escaping (Int) -> [String]) {
 37	        self.name = name
 38	        self.binaryPath = binaryPath
 39	        self.preferredPort = port
 40	        self.currentPort = port
 41	        self.session = session
 42	        self.owns = owns
 43	        self.arguments = arguments
 44	    }
 45	
 46	    deinit { shutdown() }
 47	
 48	    /// The port of the server last started or adopted.
 49	    public var port: Int { locked { currentPort } }
 50	
 51	    /// True once the server answers `/health`, polling up to `polls` times
 52	    /// (250 ms apart; a probe gives up after 1 s without data). When no child
 53	    /// of ours is running, `preflight` runs first (binary and model checks),
 54	    /// then the server is adopted or spawned. False on timeout, as soon as a
 55	    /// spawned child exits (a bad model never becomes ready), when another
 56	    /// process answered on the child's port (the child is stopped), or once
 57	    /// `shutdown()` has run.
 58	    public func ensureRunning(polls: Int, preflight: () throws -> Void) async throws -> Bool {
 59	        if await isVerifiedAndHealthy() { return true }
 60	        await gate.enter()
 61	        do {
 62	            let ready = try await start(polls: polls, preflight: preflight)
 63	            await gate.leave()
 64	            return ready
 65	        } catch {
 66	            await gate.leave()
 67	            throw error
 68	        }
 69	    }
 70	
 71	    /// Stops the child and retires the server for good.
 72	    public func shutdown() {
 73	        let child = locked { () -> Process? in
 74	            defer { process = nil; verified = false; retired = true }
 75	            return process
 76	        }
 77	        child?.terminate()
 78	    }
 79	
 80	    public static func healthRequest(port: Int) -> URLRequest {
 81	        var request = URLRequest(url: URL(string: "http://127.0.0.1:\(port)/health")!)
 82	        request.timeoutInterval = 1
 83	        return request
 84	    }
 85	
 86	    /// True when `pid`, or a process it started (a wrapper script that does
 87	    /// not `exec`), is listening on the loopback `port`.
 88	    public static func listens(pid: pid_t, port: Int) -> Bool {
 89	        LocalServer.listeningPIDs(port: port).contains {
 90	            $0 == pid || LocalServer.parentPID(of: $0) == pid
 91	        }
 92	    }
 93	
 94	    // MARK: internals
 95	
 96	    private func start(polls: Int, preflight: () throws -> Void) async throws -> Bool {
 97	        guard !locked({ retired }) else { return false }
 98	        // A caller ahead of us at the gate may have finished the start.
 99	        if await isVerifiedAndHealthy() { return true }
100	
101	        let child: Process? // nil: an adopted orphan, attributed by resolvePort
102	        let target: Int
103	        if let running = locked({ process?.isRunning == true ? process : nil }) {
104	            child = running
105	            target = port
106	        } else {
107	            try preflight()
108	            let avoid = locked { () -> Bool in
109	                // A child that exited before it was ready (after its start
110	                // gave up polling) may have lost the port as well.
111	                if process != nil && !verified { avoidPreferredPort = true }
112	                process = nil
113	                verified = false
114	                return avoidPreferredPort
115	            }
116	            let decision = avoid
117	                ? .spawn(LocalServer.freeLoopbackPort() ?? preferredPort)
118	                : LocalServer.resolvePort(preferred: preferredPort, binaryPath: binaryPath)
119	            switch decision {
120	            case .adopt(let adopted):
121	                locked { currentPort = adopted }
122	                child = nil
123	                target = adopted
124	            case .spawn(let free):
125	                let server = Process()
126	                server.executableURL = URL(fileURLWithPath: binaryPath)
127	                server.arguments = arguments(free)
128	                server.standardOutput = FileHandle.nullDevice
129	                server.standardError = FileHandle.nullDevice
130	                server.environment = LocalServer.sanitizedEnvironment()
131	                try server.run()
132	                let kept = locked { () -> Bool in
133	                    guard !retired else { return false }
134	                    process = server
135	                    currentPort = free
136	                    return true
137	                }
138	                guard kept else { // retired during this start
139	                    server.terminate()
140	                    return false
141	                }
142	                Log.info("\(name) spawned (pid \(server.processIdentifier), port \(free))")
143	                child = server
144	                target = free
145	            }
146	        }
147	
148	        for _ in 0..<polls {
149	            if await isHealthy(port: target) {
150	                // An adopted orphan is ours unless the server retired meanwhile.
151	                guard let child else { return !locked({ retired }) }
152	                let holdsPort = child.isRunning && owns(child.processIdentifier, target)
153	                // Decided under the lock: a shutdown during the probe or the
154	                // ownership check wins, and then this answer is not the child's.
155	                let current = locked { () -> Bool in
156	                    guard process === child else { return false }
157	                    if holdsPort { verified = true }
158	                    return true
159	                }
160	                guard current else { return false }
161	                if holdsPort { return true }
162	                Log.info("\(name): another process answered on port \(target); refusing it")
163	                abandon(child)
164	                return false
165	            }
166	            if let child, !child.isRunning {
167	                abandon(child)
168	                return false
169	            }
170	            try await Task.sleep(nanoseconds: 250_000_000)
171	        }
172	        return false
173	    }
174	
175	    /// Drops a child that never became ready and keeps later starts off its
176	    /// port, which may belong to a process `lsof` cannot see.
177	    private func abandon(_ child: Process) {
178	        locked {
179	            if process === child { process = nil }
180	            avoidPreferredPort = true
181	        }
182	        if child.isRunning { child.terminate() }
183	    }
184	
185	    private func isVerifiedAndHealthy() async -> Bool {
186	        guard let (child, port) = locked({ () -> (Process, Int)? in
187	            guard verified, let process, process.isRunning else { return nil }
188	            return (process, currentPort)
189	        }) else { return false }
190	        guard await isHealthy(port: port) else { return false }
191	        return locked { verified && process === child } // a shutdown during the probe wins
192	    }
193	
194	    private func isHealthy(port: Int) async -> Bool {
195	        guard let (_, response) = try? await session.data(for: Self.healthRequest(port: port))
196	        else { return false }
197	        return (response as? HTTPURLResponse)?.statusCode == 200
198	    }
199	
200	    private func locked<T>(_ body: () -> T) -> T {
201	        lock.lock()
202	        defer { lock.unlock() }
203	        return body()
204	    }
205	}
206	
207	/// Admits one caller at a time, in arrival order.
208	private actor StartGate {
209	    private var busy = false
210	    private var waiting: [CheckedContinuation<Void, Never>] = []
211	
212	    func enter() async {
213	        guard busy else {
214	            busy = true
215	            return
216	        }
217	        await withCheckedContinuation { waiting.append($0) }
218	    }
219	
220	    func leave() {
221	        if waiting.isEmpty {
222	            busy = false
223	        } else {
224	            waiting.removeFirst().resume()
225	        }
226	    }
227	}

