     1	import Foundation
     2	
     3	public enum LlamaCppError: Error, LocalizedError {
     4	    case binaryMissing(String)
     5	    case modelMissing(String)
     6	    case serverTimeout
     7	    case serverLoading
     8	    case http(status: Int)
     9	    case emptyResponse
    10	
    11	    public var errorDescription: String? {
    12	        switch self {
    13	        case .binaryMissing:
    14	            return "llama-server not installed (run scripts/install_llama.sh)"
    15	        case .modelMissing:
    16	            return "Cleanup model missing (run scripts/install_llama.sh)"
    17	        case .serverTimeout:
    18	            return "Local cleanup model didn't start"
    19	        case .serverLoading:
    20	            return "Local cleanup model still loading"
    21	        case .http(let status):
    22	            return "Local cleanup error \(status)"
    23	        case .emptyResponse:
    24	            return "Empty response from local cleanup model"
    25	        }
    26	    }
    27	}
    28	
    29	/// Local cleanup LLM: spawns and owns a warm `llama-server` child (llama.cpp,
    30	/// loopback) and speaks its OpenAI-compatible `/v1/chat/completions`. Mirrors
    31	/// `WhisperCppEngine`'s child-server lifecycle, with one refinement: readiness
    32	/// uses llama-server's `/health` (503 while the model loads, 200 when ready),
    33	/// so an orphaned-but-loading server is polled instead of re-spawned. Cleanup
    34	/// is optional, so `chatComplete` waits at most ~2s for warmth and otherwise
    35	/// throws (`Cleaner` falls back to the raw transcript) — only `warmUp()` /
    36	/// `ensureReady()` sit through a cold model load.
    37	public final class LlamaCppChatEngine: ChatEngine, LocalServerEngine, Prewarmable {
    38	    static let warmUpPolls = 240 // × 250ms = 60s — cold GGUF load
    39	    static let requestPolls = 8  // × 250ms = 2s — never make a paste wait
    40	
    41	    private let binaryPath: String
    42	    private let modelPath: String
    43	    private let preferredPort: Int
    44	    private var activePort: Int
    45	    private let session: URLSession
    46	    private var process: Process?
    47	
    48	    public init(binaryPath: String, modelPath: String, port: Int,
    49	                session: URLSession = LoopbackURLSession.make(resourceTimeout: 30)) {
    50	        self.binaryPath = binaryPath
    51	        self.modelPath = (modelPath as NSString).expandingTildeInPath
    52	        self.preferredPort = port
    53	        self.activePort = port
    54	        self.session = session
    55	    }
    56	
    57	    deinit { shutdown() }
    58	
    59	    public func chatComplete(system: String, user: String, maxTokens: Int) async throws -> String {
    60	        try await ensureServerRunning(pollBudget: Self.requestPolls)
    61	        let request = try Self.makeChatRequest(system: system, user: user,
    62	                                               maxTokens: maxTokens, port: activePort)
    63	        let (data, response) = try await session.data(for: request)
    64	        let status = (response as? HTTPURLResponse)?.statusCode ?? 0
    65	        guard status == 200 else { throw LlamaCppError.http(status: status) }
    66	        return try Self.parseChatResponse(data)
    67	    }
    68	
    69	    /// Spawns the server eagerly so the model is warm before the first
    70	    /// utterance. Safe to call repeatedly.
    71	    public func warmUp() {
    72	        Task.detached { [weak self] in
    73	            try? await self?.ensureServerRunning(pollBudget: Self.warmUpPolls)
    74	        }
    75	    }
    76	
    77	    /// Blocks through a full cold load — for tests/pre-flight, not the
    78	    /// utterance path.
    79	    public func ensureReady() async throws {
    80	        try await ensureServerRunning(pollBudget: Self.warmUpPolls)
    81	    }
    82	
    83	    /// `prompt` is the cleanup system prompt (see `Cleaner.prewarm`). Reads
    84	    /// the model file ahead (llama-server maps it) while the one-token
    85	    /// request pages in the rest.
    86	    @discardableResult
    87	    public func prewarm(prompt: String?) -> Task<Bool, Never> {
    88	        Task.detached { [weak self] in
    89	            guard let self else { return false }
    90	            async let weights: Void = Prewarm.readAheadInBackground(self.modelPath)
    91	            var answered = false
    92	            if (try? await self.ensureServerRunning(pollBudget: Self.requestPolls)) != nil {
    93	                answered = await Prewarm.send(try? Self.makePrewarmRequest(system: prompt ?? "", port: self.activePort),
    94	                                              with: self.session)
    95	            }
    96	            await weights
    97	            return answered
    98	        }
    99	    }
   100	
   101	    public func shutdown() {
   102	        process?.terminate()
   103	        process = nil
   104	    }
   105	
   106	    // MARK: server lifecycle (mirrors WhisperCppEngine, /health-aware)
   107	
   108	    private enum Health { case ready, loading, down }
   109	
   110	    private func health() async -> Health {
